import{_ as n,a0 as p,w as o,s as r,I as s,x as t,a1 as l,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Git 使用簡介 | LCTT x X-CMD","titleTemplate":false,"description":"Git 使用簡介 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 使用簡介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 使用簡介 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180720 An Introduction to Using Git","title":"Git 使用簡介","tag":"201809","desc":""},"relativePath":"201809/20180720 An Introduction to Using Git.md","filePath":"[post].md"}'),g={name:"201809/20180720 An Introduction to Using Git.md"};function u(h,i,b,k,m,c){const e=p("Link");return o(),r("div",null,[i[26]||(i[26]=s("h1",{id:"git-使用簡介",tabindex:"-1"},[t("Git 使用簡介 "),s("a",{class:"header-anchor",href:"#git-使用簡介","aria-label":"Permalink to “Git 使用簡介”"},"​")],-1)),i[27]||(i[27]=s("blockquote",null,[s("p",null,"我將向你介紹讓 Git 的啓動、運行，並和 GitHub 一起使用的基礎知識。")],-1)),i[28]||(i[28]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/developer-3461405_1920.png?itok=6H3sYe80",alt:""})],-1)),i[29]||(i[29]=s("p",null,"如果你是一個開發者，那你應該熟悉許多開發工具。你已經花了多年時間來學習一種或者多種編程語言並打磨你的技巧。你可以熟練運用圖形工具或者命令列工具開發。在你看來，沒有任何事可以阻擋你。你的代碼, 好像你的思想和你的手指一樣，將會創建一個優雅的，完美評價的應用程序，並會風靡世界。",-1)),s("p",null,[i[2]||(i[2]=t("然而，如果你和其他人共同開發一個項目會發生什麼呢？或者，你開發的應用程序變地越來越大，下一步你將如何去做？如果你想成功地和其他開發者合作，你定會想用一個分佈式版本控制系統。使用這樣一個系統，合作開發一個項目變得非常高效和可靠。這樣的一個系統便是 ",-1)),l(e,{href:"https://git-scm.com/"},{default:a(()=>[...i[0]||(i[0]=[t("Git",-1)])]),_:1}),i[3]||(i[3]=t("。還有一個叫 ",-1)),l(e,{href:"https://github.com/"},{default:a(()=>[...i[1]||(i[1]=[t("GitHub",-1)])]),_:1}),i[4]||(i[4]=t(" 的方便的存儲倉庫，用來存儲你的項目代碼，這樣你的團隊可以檢查和修改代碼。",-1))]),i[30]||(i[30]=s("p",null,"我將向你介紹讓 Git 的啓動、運行，並和 GitHub 一起使用的基礎知識，可以讓你的應用程序的開發可以提升到一個新的水平。我將在 Ubuntu 18.04 上進行演示，因此如果您選擇的發行版本不同，您只需要修改 Git 安裝命令以適合你的發行版的軟件包管理器。",-1)),i[31]||(i[31]=s("h3",{id:"git-和-github",tabindex:"-1"},[t("Git 和 GitHub "),s("a",{class:"header-anchor",href:"#git-和-github","aria-label":"Permalink to “Git 和 GitHub”"},"​")],-1)),s("p",null,[i[6]||(i[6]=t("第一件事就是創建一個免費的 GitHub 賬號，打開 ",-1)),l(e,{href:"https://github.com/join?source=header-home"},{default:a(()=>[...i[5]||(i[5]=[t("GitHub 註冊頁面",-1)])]),_:1}),i[7]||(i[7]=t("，然後填上需要的信息。完成這個之後，你就注備好開始安裝 Git 了（這兩件事誰先誰後都可以）。",-1))]),i[32]||(i[32]=d(`<p>安裝 Git 非常簡單，打開一個命令列終端，並輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install git-all</span></span></code></pre></div><p>這將會安裝大量依賴包，但是你將瞭解使用 Git 和 GitHub 所需的一切。</p><p>附註：我使用 Git 來下載程序的安裝源碼。有許多時候，內置的軟件管理器不提供某個軟件，除了去第三方庫中下載源碼，我經常去這個軟件項目的 Git 主頁，像這樣克隆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone ADDRESS</span></span></code></pre></div><p>“ADDRESS” 就是那個軟件項目的 Git 主頁。這樣我就可以確保自己安裝那個軟件的最新發行版了。</p><h3 id="創建一個本地倉庫並添加一個文件" tabindex="-1">創建一個本地倉庫並添加一個文件 <a class="header-anchor" href="#創建一個本地倉庫並添加一個文件" aria-label="Permalink to “創建一個本地倉庫並添加一個文件”">​</a></h3><p>下一步就是在你的電腦裏創建一個本地倉庫（本文稱之為 newproject，位於 <code>~/</code> 目錄下），打開一個命令列終端，並輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~/</span></span>
<span class="line"><span>mkdir newproject</span></span>
<span class="line"><span>cd newproject</span></span></code></pre></div><p>現在你需要初始化這個倉庫。在 <code>~/newproject</code> 目錄下，輸入命令 <code>git init</code>，當命令運行完，你就可以看到一個剛剛創建的空的 Git 倉庫了（圖1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_1.jpg?itok=FKkr5Mrk" alt="new repository" title="new repository"></p><p><em>圖 1: 初始化完成的新倉庫</em></p><p>下一步就是往項目裏添加文件。我們在項目根目錄（<code>~/newproject</code>）輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch readme.txt</span></span></code></pre></div><p>現在項目裏多了個空文件。輸入 <code>git status</code> 來驗證 Git 已經檢測到多了個新文件（圖2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_2.jpg?itok=54G9KBHS" alt="readme" title="readme"></p><p><em>圖 2: Git 檢測到新文件readme.txt</em></p><p>即使 Git 檢測到新的文件，但它並沒有被真正的加入這個項目倉庫。為此，你要輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add readme.txt</span></span></code></pre></div><p>一旦完成這個命令，再輸入 <code>git status</code> 命令，可以看到，<code>readme.txt</code> 已經是這個項目裏的新文件了（圖3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_3.jpg?itok=KAJwRJIB" alt="file added" title="file added"></p><p><em>圖 3: 我們的文件已經被添加進臨時環境</em></p><h3 id="第一次提交" tabindex="-1">第一次提交 <a class="header-anchor" href="#第一次提交" aria-label="Permalink to “第一次提交”">​</a></h3><p>當新文件添加進臨時環境之後，我們現在就準備好創建第一個<ruby>提交<rt>commit</rt></ruby>了。什麼是提交呢？簡單的説，一個提交就是你更改的項目的文件的記錄。創建一個提交也是非常簡單的。但是，為提交包含一個描述信息非常重要。通過這樣做，你可以添加有關該提交包含的內容的註釋，比如你對文件做出的何種修改。然而，在這樣做之前，我們需要告知 Git 我們的賬户，輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git config --global user.email EMAIL</span></span>
<span class="line"><span>git config --global user.name “FULL NAME”</span></span></code></pre></div><p>“EMAIL” 即你的 email 地址，“FULL NAME” 則是你的姓名。</p><p>現在你可以通過以下命令創建一個提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m “Descriptive Message”</span></span></code></pre></div><p>“Descriptive Message” 即為你的提交的描述性信息。比如，當你第一個提交是提交一個 <code>readme.txt</code> 文件，你可以這樣提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m “First draft of readme.txt file”</span></span></code></pre></div><p>你可以看到輸出表明一個文件已經修改，並且，為 <code>readme.txt</code> 創建了一個新的文件模式（圖4）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_4.jpg?itok=qR0ighDz" alt="success" title="success"></p><p><em>圖4：提交成功</em></p><h3 id="創建分支並推送至-github" tabindex="-1">創建分支並推送至 GitHub <a class="header-anchor" href="#創建分支並推送至-github" aria-label="Permalink to “創建分支並推送至 GitHub”">​</a></h3><p>分支是很重要的，它允許你在項目狀態間中移動。假如，你想給你的應用創建一個新的特性。為了這樣做，你創建了個新分支。一旦你完成你的新特性，你可以把這個新分支合併到你的主分支中去，使用以下命令創建一個新分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git checkout -b BRANCH</span></span></code></pre></div><p>“BRANCH” 即為你新分支的名字，一旦執行完命令，輸入 <code>git branch</code> 命令來查看是否創建了新分支（圖5）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_5.jpg?itok=6m9RTWg6" alt="featureX" title="featureX"></p><p><em>圖5:名為 featureX 的新分支</em></p><p>接下來，我們需要在 GitHub 上創建一個倉庫。 登錄 GitHub 帳户，請單擊帳户主頁上的“New Repository”按鈕。 填寫必要的信息，然後單擊 “Create repository”（圖6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_6.jpg?itok=d2toRrUq" alt="new repository" title="new repository"></p><p><em>圖6:在 GitHub 上新建一個倉庫</em></p><p>在創建完一個倉庫之後，你可以看到一個用於推送本地倉庫的地址。若要推送，返回命令列窗口（<code>~/newproject</code> 目錄中），輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git remote add origin URL</span></span>
<span class="line"><span>git push -u origin master</span></span></code></pre></div><p>“URL” 即為我們 GitHub 上新建的倉庫地址。</p><p>系統會提示您，輸入 GitHub 的用户名和密碼，一旦授權成功，你的項目將會被推送到 GitHub 倉庫中。</p><h3 id="拉取項目" tabindex="-1">拉取項目 <a class="header-anchor" href="#拉取項目" aria-label="Permalink to “拉取項目”">​</a></h3><p>如果你的同事改變了你們 GitHub 上項目的代碼，並且已經合併那些更改，你可以拉取那些項目文件到你的本地機器，這樣，你係統中的文件就可以和遠程用户的文件保持匹配。你可以輸入以下命令來做這件事（<code>~/newproject</code> 在目錄中），</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git pull origin master</span></span></code></pre></div><p>以上的命令可以拉取任何新文件或修改過的文件到你的本地倉庫。</p><h3 id="基礎" tabindex="-1">基礎 <a class="header-anchor" href="#基礎" aria-label="Permalink to “基礎”">​</a></h3><p>這就是從命令列使用 Git 來處理存儲在 GitHub 上的項目的基礎知識。 還有很多東西需要學習，所以我強烈建議你使用 <code>man git</code>，<code>man git-push</code> 和 <code>man git-pull</code> 命令來更深入地瞭解 <code>git</code> 命令可以做什麼。</p><p>開發快樂！</p>`,53)),s("p",null,[i[9]||(i[9]=t("瞭解更多關於 Linux 的 內容，請訪問來自 Linux 基金會和 edX 的免費的 ",-1)),l(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:a(()=>[...i[8]||(i[8]=[t('"Introduction to Linux"',-1)])]),_:1}),i[10]||(i[10]=t("課程。",-1))]),i[33]||(i[33]=s("hr",null,null,-1)),s("p",null,[i[12]||(i[12]=t("via: ",-1)),l(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/7/introduction-using-git"},{default:a(()=>[...i[11]||(i[11]=[t("https://www.linux.com/learn/intro-to-linux/2018/7/introduction-using-git",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...i[13]||(i[13]=[t("Jack Wallen",-1)])]),_:1}),i[18]||(i[18]=t(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[14]||(i[14]=[t("lujun9972",-1)])]),_:1}),i[19]||(i[19]=t(" 譯者：",-1)),l(e,{href:"https://github.com/distant1219"},{default:a(()=>[...i[15]||(i[15]=[t("distant1219",-1)])]),_:1}),i[20]||(i[20]=t(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[16]||(i[16]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[23]||(i[23]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[21]||(i[21]=[t("LCTT",-1)])]),_:1}),i[24]||(i[24]=t(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...i[22]||(i[22]=[t("Linux中國",-1)])]),_:1}),i[25]||(i[25]=t(" 榮譽推出",-1))])])}const w=n(g,[["render",u]]);export{y as __pageData,w as default};
